import{_ as n,o as s,c as p,a2 as t}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Agent 自主度分级：辅助、半自主与全自主","description":"","frontmatter":{},"headers":[],"relativePath":"zh/learn/01-agent-basics/autonomy-levels.md","filePath":"zh/learn/01-agent-basics/autonomy-levels.md","lastUpdated":1792545482000}'),l={name:"zh/learn/01-agent-basics/autonomy-levels.md"};function e(i,a,d,r,o,h){return s(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="agent-自主度分级-辅助、半自主与全自主" tabindex="-1">Agent 自主度分级：辅助、半自主与全自主 <a class="header-anchor" href="#agent-自主度分级-辅助、半自主与全自主" aria-label="Permalink to &quot;Agent 自主度分级：辅助、半自主与全自主&quot;">​</a></h1><h2 id="一、为什么要区分-agent-的自主度" tabindex="-1">一、为什么要区分 Agent 的自主度？ <a class="header-anchor" href="#一、为什么要区分-agent-的自主度" aria-label="Permalink to &quot;一、为什么要区分 Agent 的自主度？&quot;">​</a></h2><p>同样是 AI Agent，不同系统能够自行决定和执行的事情可能完全不同。</p><p>例如：</p><ul><li>Agent A：分析一份报告，并提出修改建议。</li><li>Agent B：分析报告、修改文件，最后等待用户确认。</li><li>Agent C：自动分析报告、修改文件并发布到指定平台。</li></ul><p>三者都可以使用大模型和工具，但它们获得的执行权限不同。</p><p>如果不区分自主度，就很难回答一个关键问题：</p><p><strong>哪些事情可以让 Agent 自己决定，哪些事情必须由人来确认？</strong></p><p>自主度分级，就是帮助我们明确 Agent 的决策权、执行权和人工介入要求。</p><h2 id="二、三个常见的自主度级别" tabindex="-1">二、三个常见的自主度级别 <a class="header-anchor" href="#二、三个常见的自主度级别" aria-label="Permalink to &quot;二、三个常见的自主度级别&quot;">​</a></h2><p>本文采用一个便于工程实践的三级划分：辅助式、半自主式和全自主式。</p><p>这是一种用于理解和设计系统的实用分类，并非适用于所有行业的统一标准。</p><h3 id="_1-辅助式-agent-人决定-ai-辅助" tabindex="-1">1. 辅助式 Agent：人决定，AI 辅助 <a class="header-anchor" href="#_1-辅助式-agent-人决定-ai-辅助" aria-label="Permalink to &quot;1. 辅助式 Agent：人决定，AI 辅助&quot;">​</a></h3><p>在辅助式模式下，AI 主要负责分析信息、生成建议或准备操作，人类负责决定是否执行。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提出任务</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>AI 分析信息</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>AI 生成建议</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>用户检查结果</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>用户决定是否执行</span></span></code></pre></div><p>典型场景：</p><ul><li>生成文章草稿。</li><li>分析业务数据。</li><li>提供代码修改建议。</li><li>生成待审批的操作方案。</li></ul><p>这种模式适合高风险场景的早期探索，也适合执行结果需要人工判断的任务。</p><p>优点：</p><ul><li>人类保留最终决定权。</li><li>容易发现明显错误。</li><li>不容易因为模型误判而直接执行外部操作。</li></ul><p>缺点：</p><ul><li>需要人工参与。</li><li>任务处理速度可能较慢。</li><li>人工检查仍可能遗漏问题。</li></ul><p>需要注意：辅助式 Agent 即使不直接执行操作，也可能生成错误建议，因此关键结果仍需要核验。</p><h3 id="_2-半自主式-agent-ai-执行-人类把关" tabindex="-1">2. 半自主式 Agent：AI 执行，人类把关 <a class="header-anchor" href="#_2-半自主式-agent-ai-执行-人类把关" aria-label="Permalink to &quot;2. 半自主式 Agent：AI 执行，人类把关&quot;">​</a></h3><p>在半自主式模式下，Agent 可以在预先规定的范围内执行任务，但某些操作需要人工批准。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提出任务</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>AI 分析任务</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>AI 执行低风险步骤</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>是否需要审批？</span></span>
<span class="line"><span>   ┌─┴────┐</span></span>
<span class="line"><span>   │      │</span></span>
<span class="line"><span>  需要   不需要</span></span>
<span class="line"><span>   │      │</span></span>
<span class="line"><span>人工审批 继续执行</span></span>
<span class="line"><span>   │      │</span></span>
<span class="line"><span>   └──┬───┘</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>   完成任务</span></span></code></pre></div><p>典型场景：</p><ul><li>自动搜索并整理行业资料。</li><li>自动生成报告，提交后等待审核。</li><li>自动生成邮件草稿，发送前由人确认。</li><li>自动分析交易机会，但下单需要授权。</li></ul><p>这种模式兼顾了自动化效率与人工控制。</p><p>但审批机制必须真正有效。</p><p>如果 Agent 可以绕过审批接口直接调用底层工具，那么表面上的审批流程并不能形成可靠的安全边界。</p><h3 id="_3-全自主式-agent-在授权范围内自动执行" tabindex="-1">3. 全自主式 Agent：在授权范围内自动执行 <a class="header-anchor" href="#_3-全自主式-agent-在授权范围内自动执行" aria-label="Permalink to &quot;3. 全自主式 Agent：在授权范围内自动执行&quot;">​</a></h3><p>在全自主式模式下，Agent 可以在预先授权的范围内，自主决定并执行任务，无需每一步都等待人工确认。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接收任务</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>分析目标</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>选择工具</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>执行操作</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>检查结果</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>继续调整</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>达到目标或触发停止条件</span></span></code></pre></div><p>典型场景：</p><ul><li>按固定规则整理文件。</li><li>自动监控公开数据并生成日报。</li><li>在严格限额内调用付费 API。</li><li>根据明确规则处理低风险、可逆的业务操作。</li></ul><p>全自主并不意味着没有限制。</p><p>一个合理的全自主系统仍然需要：</p><ul><li>明确的授权范围。</li><li>工具权限隔离。</li><li>最大执行次数。</li><li>时间和资源限制。</li><li>错误处理与恢复机制。</li><li>可追踪的执行记录。</li><li>必要时的自动停止机制。</li></ul><p><strong>全自主描述的是执行过程中是否需要逐步等待人工批准，而不是 Agent 是否拥有无限权限。</strong></p><h2 id="三、三种模式的对比" tabindex="-1">三、三种模式的对比 <a class="header-anchor" href="#三、三种模式的对比" aria-label="Permalink to &quot;三、三种模式的对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>辅助式</th><th>半自主式</th><th>全自主式</th></tr></thead><tbody><tr><td>任务分析</td><td>AI 参与</td><td>AI 参与</td><td>AI 参与</td></tr><tr><td>操作执行</td><td>主要由人决定并执行</td><td>AI 可执行部分步骤</td><td>AI 在授权范围内执行</td></tr><tr><td>人工介入</td><td>通常较多</td><td>在关键节点介入</td><td>不要求逐步批准</td></tr><tr><td>自动化程度</td><td>较低</td><td>中等</td><td>较高</td></tr><tr><td>运行效率</td><td>受人工流程影响</td><td>兼顾效率与控制</td><td>在合适任务中效率较高</td></tr><tr><td>主要风险</td><td>错误建议被采纳</td><td>审批机制被绕过</td><td>错误可能自动传播</td></tr><tr><td>适合场景</td><td>高风险决策、探索阶段</td><td>需要关键节点审批的流程</td><td>边界明确、可监控的任务</td></tr></tbody></table><p>这三种模式不是简单的优劣排名。</p><p>对于低风险任务，全自主可能更高效；对于高风险操作，辅助式或半自主式往往更合适。</p><h2 id="四、自主度不等于权限大小" tabindex="-1">四、自主度不等于权限大小 <a class="header-anchor" href="#四、自主度不等于权限大小" aria-label="Permalink to &quot;四、自主度不等于权限大小&quot;">​</a></h2><p>这是设计 Agent 时最容易混淆的概念之一。</p><p>自主度回答的是：</p><blockquote><p>Agent 可以在多大程度上自行决定下一步？</p></blockquote><p>权限回答的是：</p><blockquote><p>Agent 被允许执行哪些操作？</p></blockquote><p>两者相互关联，但并不相同。</p><p>例如，一个 Agent 可以自主分析数据、选择查询策略，但只拥有只读数据库权限。</p><p>另一个 Agent 可能每一步都需要人工确认，却仍然拥有范围过大的文件系统访问权限。</p><p>因此，不能仅通过自主度判断系统是否安全。</p><p>设计时应分别考虑：</p><ol><li>决策自主度。</li><li>工具访问权限。</li><li>资金或资源限额。</li><li>人工审批要求。</li><li>运行时间与调用次数限制。</li></ol><h2 id="五、如何决定某个任务应该采用哪种模式" tabindex="-1">五、如何决定某个任务应该采用哪种模式？ <a class="header-anchor" href="#五、如何决定某个任务应该采用哪种模式" aria-label="Permalink to &quot;五、如何决定某个任务应该采用哪种模式？&quot;">​</a></h2><p>可以从四个维度判断。</p><h3 id="_1-操作风险" tabindex="-1">1. 操作风险 <a class="header-anchor" href="#_1-操作风险" aria-label="Permalink to &quot;1. 操作风险&quot;">​</a></h3><p>操作一旦执行，可能造成多大损失？</p><p>例如：</p><ul><li>搜索公开信息：通常风险较低。</li><li>修改共享文件：可能影响其他人。</li><li>删除生产数据：风险较高。</li><li>转移真实资金：需要严格授权与控制。</li></ul><p>风险越高，通常越需要限制权限或增加审批。</p><h3 id="_2-操作是否可逆" tabindex="-1">2. 操作是否可逆 <a class="header-anchor" href="#_2-操作是否可逆" aria-label="Permalink to &quot;2. 操作是否可逆&quot;">​</a></h3><p>如果操作出错，能否恢复？</p><p>例如：</p><ul><li>生成一份草稿：通常可以重新生成。</li><li>修改文件：可能需要版本控制或备份。</li><li>删除数据：恢复成本可能较高。</li><li>已完成的链上交易：通常不能像普通数据库更新那样直接撤销。</li></ul><p>越难撤销的操作，越应该谨慎设计自动执行条件。</p><h3 id="_3-结果是否容易验证" tabindex="-1">3. 结果是否容易验证 <a class="header-anchor" href="#_3-结果是否容易验证" aria-label="Permalink to &quot;3. 结果是否容易验证&quot;">​</a></h3><p>如果系统能够通过明确规则判断结果是否正确，就更容易实现自动化。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查文件是否存在</span></span>
<span class="line"><span>检查 HTTP 状态码</span></span>
<span class="line"><span>检查金额是否超过限额</span></span>
<span class="line"><span>检查任务是否达到完成条件</span></span></code></pre></div><p>如果结果高度依赖主观判断，或者缺乏可靠的数据来源，就可能需要人工复核。</p><h3 id="_4-失败后能否安全恢复" tabindex="-1">4. 失败后能否安全恢复 <a class="header-anchor" href="#_4-失败后能否安全恢复" aria-label="Permalink to &quot;4. 失败后能否安全恢复&quot;">​</a></h3><p>如果执行失败，系统能否确认实际状态？</p><p>例如，一次 HTTP 请求超时，并不能证明服务端没有执行操作。</p><p>如果无法确认执行结果，系统就不应该简单地重复执行敏感操作。</p><p>需要先查询状态，或者进入专门的恢复流程。</p><h2 id="六、建立任务风险与自主度的对应关系" tabindex="-1">六、建立任务风险与自主度的对应关系 <a class="header-anchor" href="#六、建立任务风险与自主度的对应关系" aria-label="Permalink to &quot;六、建立任务风险与自主度的对应关系&quot;">​</a></h2><p>下面是一种实用的初始设计方案：</p><table tabindex="0"><thead><tr><th>任务类型</th><th>建议模式</th><th>主要控制措施</th></tr></thead><tbody><tr><td>公开信息搜索</td><td>全自主式</td><td>调用限额、来源校验</td></tr><tr><td>文章草稿生成</td><td>辅助式或全自主式</td><td>内容审核、发布权限隔离</td></tr><tr><td>发送外部邮件</td><td>半自主式</td><td>收件人校验、发送前审批</td></tr><tr><td>修改生产数据</td><td>半自主式或受限自动执行</td><td>权限隔离、事务、备份、审计</td></tr><tr><td>执行真实资金转移</td><td>严格授权下的受限自动执行，必要时人工审批</td><td>金额限额、收款方校验、幂等、状态核验</td></tr></tbody></table><p>这里的模式是设计建议，不是绝对规则。</p><p>例如，发送邮件也可以在明确授权的低风险场景中自动执行；资金操作也可以在严格限定的业务条件下实现自动化。但不能因为系统具备自动执行能力，就跳过相应的安全设计。</p><h2 id="七、工程上如何控制-agent-的自主度" tabindex="-1">七、工程上如何控制 Agent 的自主度？ <a class="header-anchor" href="#七、工程上如何控制-agent-的自主度" aria-label="Permalink to &quot;七、工程上如何控制 Agent 的自主度？&quot;">​</a></h2><p>自主度不能只通过提示词控制，还应落实到程序架构中。</p><h3 id="_1-限制工具范围" tabindex="-1">1. 限制工具范围 <a class="header-anchor" href="#_1-限制工具范围" aria-label="Permalink to &quot;1. 限制工具范围&quot;">​</a></h3><p>为不同任务注册不同的工具。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据分析 Agent</span></span>
<span class="line"><span>  ├── 查询公开数据</span></span>
<span class="line"><span>  └── 生成报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不默认提供：</span></span>
<span class="line"><span>  ├── 删除生产数据</span></span>
<span class="line"><span>  ├── 修改账户权限</span></span>
<span class="line"><span>  └── 转移资金</span></span></code></pre></div><p>没有必要的工具，就不应默认暴露给 Agent。</p><h3 id="_2-为工具设置权限" tabindex="-1">2. 为工具设置权限 <a class="header-anchor" href="#_2-为工具设置权限" aria-label="Permalink to &quot;2. 为工具设置权限&quot;">​</a></h3><p>即使两个 Agent 都可以查询数据库，它们能够访问的数据范围也可以不同。</p><p>例如：</p><ul><li>Agent A 只能读取公开数据。</li><li>Agent B 可以读取某个项目的数据。</li><li>Agent C 可以在审批后修改指定记录。</li></ul><p>权限应由可信的服务端执行，而不是仅靠模型自行遵守。</p><h3 id="_3-设置预算和执行上限" tabindex="-1">3. 设置预算和执行上限 <a class="header-anchor" href="#_3-设置预算和执行上限" aria-label="Permalink to &quot;3. 设置预算和执行上限&quot;">​</a></h3><p>可以限制：</p><ul><li>单次任务最大调用次数。</li><li>单次任务最大运行时间。</li><li>模型调用预算。</li><li>API 消费额度。</li><li>单次操作金额。</li><li>一段时间内的累计操作额度。</li></ul><p>这些限制可以降低任务循环和错误决策带来的影响。</p><h3 id="_4-为敏感操作设置审批点" tabindex="-1">4. 为敏感操作设置审批点 <a class="header-anchor" href="#_4-为敏感操作设置审批点" aria-label="Permalink to &quot;4. 为敏感操作设置审批点&quot;">​</a></h3><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 生成操作请求</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>程序验证请求</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>判断是否需要审批</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>人工确认</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>服务端重新校验</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>执行操作</span></span></code></pre></div><p>审批不能只是一条对话消息。</p><p>系统应确保实际执行路径确实受到审批状态约束，并防止请求被替换或重复执行。</p><h3 id="_5-记录执行过程" tabindex="-1">5. 记录执行过程 <a class="header-anchor" href="#_5-记录执行过程" aria-label="Permalink to &quot;5. 记录执行过程&quot;">​</a></h3><p>至少应记录：</p><ul><li>任务标识。</li><li>调用了什么工具。</li><li>关键参数与校验结果。</li><li>操作是否成功。</li><li>失败原因。</li><li>是否触发审批或停止条件。</li></ul><p>对于敏感信息，应按照数据最小化原则处理日志，避免把密钥等机密内容直接写入日志。</p><h2 id="八、一个逐步提升自主度的实践路线" tabindex="-1">八、一个逐步提升自主度的实践路线 <a class="header-anchor" href="#八、一个逐步提升自主度的实践路线" aria-label="Permalink to &quot;八、一个逐步提升自主度的实践路线&quot;">​</a></h2><p>开发 Agent 时，可以从低自主度开始，再根据验证结果逐步增加自动化程度。</p><h3 id="阶段一-只生成建议" tabindex="-1">阶段一：只生成建议 <a class="header-anchor" href="#阶段一-只生成建议" aria-label="Permalink to &quot;阶段一：只生成建议&quot;">​</a></h3><p>Agent 分析任务，但不直接执行外部操作。</p><p>重点验证模型是否理解目标、结果是否准确。</p><h3 id="阶段二-自动执行只读操作" tabindex="-1">阶段二：自动执行只读操作 <a class="header-anchor" href="#阶段二-自动执行只读操作" aria-label="Permalink to &quot;阶段二：自动执行只读操作&quot;">​</a></h3><p>允许 Agent 查询数据、搜索信息和读取文件。</p><p>重点验证工具选择、权限隔离和执行日志。</p><h3 id="阶段三-执行可逆操作" tabindex="-1">阶段三：执行可逆操作 <a class="header-anchor" href="#阶段三-执行可逆操作" aria-label="Permalink to &quot;阶段三：执行可逆操作&quot;">​</a></h3><p>允许 Agent 在受控环境中修改草稿、创建临时文件或执行其他容易恢复的操作。</p><p>重点验证错误恢复、状态管理和重复执行保护。</p><h3 id="阶段四-有限范围内自动执行" tabindex="-1">阶段四：有限范围内自动执行 <a class="header-anchor" href="#阶段四-有限范围内自动执行" aria-label="Permalink to &quot;阶段四：有限范围内自动执行&quot;">​</a></h3><p>为明确授权的操作配置额度、频率、审批条件和停止规则。</p><p>重点验证异常情况下系统能否安全停止，以及能否恢复到可确认的状态。</p><h3 id="阶段五-根据实际风险决定是否扩大权限" tabindex="-1">阶段五：根据实际风险决定是否扩大权限 <a class="header-anchor" href="#阶段五-根据实际风险决定是否扩大权限" aria-label="Permalink to &quot;阶段五：根据实际风险决定是否扩大权限&quot;">​</a></h3><p>只有在系统已经通过充分测试、监控和安全评估后，才考虑扩大自动执行范围。</p><p><strong>自主度应该根据验证结果逐步提升，而不是一开始就把所有权限交给 Agent。</strong></p><h2 id="九、小结" tabindex="-1">九、小结 <a class="header-anchor" href="#九、小结" aria-label="Permalink to &quot;九、小结&quot;">​</a></h2><p>Agent 自主度可以分为三种常见模式：</p><ul><li><strong>辅助式</strong>：AI 提供建议，人类决定和执行。</li><li><strong>半自主式</strong>：AI 可以执行部分任务，关键操作需要审批。</li><li><strong>全自主式</strong>：AI 可以在预先授权的范围内自动完成任务。</li></ul><p>真正重要的不是让 Agent 尽可能自主，而是明确它可以做什么、不能做什么，以及出错后如何停止和恢复。</p><p>可以记住一个原则：</p><p><strong>自主度决定 Agent 可以自行决定多少事情，权限决定 Agent 实际能够执行什么操作，安全机制则负责限制错误和风险的影响范围。</strong></p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p>完成本章后，你应该能够：</p><ol><li>解释 LLM、工作流与 Agent 的区别。</li><li>理解工具调用的基本流程。</li><li>解释 MCP 如何标准化外部能力的连接。</li><li>了解 LangChain、LangGraph 和 CrewAI 等框架的定位。</li><li>识别幻觉、提示词注入、无限循环和重试风暴等常见风险。</li><li>根据任务风险设计合理的自主度和权限边界。</li></ol><p>下一步，可以进入第二章，了解 Agent 为什么需要支付能力，以及现有支付方式面临哪些问题。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p><a href="./../02-agent-payments/why-agents-pay">Agent 为什么需要花钱：API、数据、算力与其他 Agent</a></p>`,140)])])}const g=n(l,[["render",e]]);export{u as __pageData,g as default};
